'use client';
const require_search = require("./search.cjs");
const require_search_button = require("./search-button.cjs");
const require_search_clear = require("./search-clear.cjs");
const require_search_input = require("./search-input.cjs");
//#region src/components/search/index.ts
/**
* Search component, use to display different variations of a search input
*
* @example with button
* <Search>
*   <Search.Input aria-label='Søk' />
*   <Search.Clear />
*   <Search.Button />
* </Search>
*
* @example with icon
* <Search>
*   <Search.Input aria-label='Søk' />
*   <Search.Clear />
* </Search>
*/
const SearchComponent = Object.assign(require_search.Search, {
	Clear: require_search_clear.SearchClear,
	Button: require_search_button.SearchButton,
	Input: require_search_input.SearchInput
});
SearchComponent.Clear.displayName = "Search.Clear";
SearchComponent.Button.displayName = "Search.Button";
SearchComponent.Input.displayName = "Search.Input";
//#endregion
exports.Search = SearchComponent;
exports.SearchButton = require_search_button.SearchButton;
exports.SearchClear = require_search_clear.SearchClear;
exports.SearchInput = require_search_input.SearchInput;
